import * as React from "react";
import { View, Text, StyleSheet } from "react-native";

export function JobDetails({ title, description }) {
  return (
    <View style={styles.detailsContainer}>
      <Text style={styles.title}>{title}</Text>
      <Text style={styles.description}>{description}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  detailsContainer: {
    display: "flex",
    marginTop: 16,
    width: "100%",
    flexDirection: "column",
    alignItems: "stretch",
  },
  title: {
    color: "#1D1D1D",
    fontSize: 20,
    fontWeight: "500",
    lineHeight: 28,
  },
  description: {
    color: "#878787",
    fontSize: 16,
    fontWeight: "400",
    lineHeight: 24,
    marginTop: 8,
  },
});
